#!/usr/bin/env python3
"""Build the offline N17 third-order analytical-family page."""
from pathlib import Path
import html,json,re
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def tex(value,display=False):
    tag='div' if display else 'span'
    return '<'+tag+' class="math" data-tex="'+html.escape(value,quote=True)+'"'+(' data-display="true"' if display else '')+'></'+tag+'>'
def main():
    assert json.loads((HERE/'verification.json').read_text())['passed']
    family=json.loads((HERE/'family-verification.json').read_text());assert family['passed']
    css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-spin2-inertia/index.html').read_text(),re.S).group(1)
    css='\n'.join(line.rstrip() for line in css.split('\n'))
    css+='\n.section-nav{display:flex;flex-wrap:wrap;gap:.7rem 1.2rem;margin:2rem 0}.formula-card{padding:1.3rem;background:#fffdf8;border:1px solid #d8d5cc;border-radius:5px;margin:1.5rem 0}.download-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1rem}.download-grid a{display:block}.download-grid small{display:block;color:#68675f}.math[data-display="true"]{overflow-x:auto}.source-note{border-left:3px solid #8c6a9e;padding:.4rem 1rem}.parameter-label{font-size:.76rem;letter-spacing:.12em;text-transform:uppercase;color:#6e5a80;font-weight:700}\n'
    pieces=[];add=pieces.append
    add('<p class="eyebrow">Anticoherent subspaces · Exact radical family</p><a class="back-link" href="../../index.html#n=17&amp;t=3&amp;subspace=radical-n17-k2-t3">← Return to the catalogue</a><h1>Seventeen qubits at third order</h1><p class="lead">An explicit analytical family of two-dimensional AC subspaces. One exactly specified member reconstructs the reported numerical Julia plane; a simpler member gives a compact radical witness.</p><div class="result"><strong>Proved maximum dimension</strong>'+tex(r'\boxed{K(17,3)=2}',True)+'<p>Every normalized complex superposition in each displayed plane is third-order anticoherent.</p></div><nav class="section-nav" aria-label="On this page"><a href="#basis">Analytical basis</a><a href="#constants">All coefficient definitions</a><a href="#proof">Full-span proof</a><a href="#source">Source reconstruction</a><a href="#files">Downloads</a></nav>')
    add('<section id="basis"><h2>An explicit radical basis</h2><p>Use normalized Dicke states, with the superscript counting excitations. The finite formulas below determine every coefficient using rational operations and square roots.</p><div class="formula-card">'+tex(r'\begin{aligned}|u\rangle&=\sum_{i=0}^{4}\sqrt{\binom{17}{4i}}\,a_i|D_{17}^{(4i)}\rangle,\\|v\rangle&=\sum_{i=0}^{4}\sqrt{\binom{17}{4i+1}}\,b_i|D_{17}^{(4i+1)}\rangle.\end{aligned}',True)+tex(r'a_0=\sqrt{P_0},\qquad a_{i+1}=\frac{a_i e_i}{h_i x_i}\ (0\le i\le3),\qquad b_i=\overline{\frac{x_i}{a_i}}.',True)+'<p>All other Dicke coefficients vanish. The symbols '+tex(r'P_i,e_i,h_i,x_i')+' are defined explicitly below.</p></div><p class="parameter-label">To reconstruct the reported Julia plane</p>'+tex(r'p_* =\frac{18370114016312017}{10^{17}},\qquad r_* =\frac{47980997065595143}{10^{17}}.',True)+'<p>These are exact rational parameters of the radical family. After a common collective rotation and separate basis phases, the coefficients agree with the supplied numerical vectors within '+tex(r'2.48\times10^{-10}')+'. <a href="source-reconstruction.json">Download all expanded radical coefficients for this member ↓</a></p><p class="parameter-label">The simpler catalogue representative</p>'+tex(r'p=\frac5{24},\qquad r=1.',True)+'<p>This choice gives shorter coefficients and the same proved optimal dimension. It is a different member of the analytical family. <a href="basis.json">Download its expanded coefficients ↓</a></p></section>')
    add('<section id="constants"><h2>All coefficient definitions</h2><p>The real parameters are '+tex(r'p,r')+'. Set '+tex(r'q=241/768-p')+'. Lists are indexed starting at zero.</p>'+tex(r'\begin{aligned}\boldsymbol P={}&\left(p-\frac{65}{768},\frac{799}{768}-4p,6p-\frac{731}{768},\frac{255}{256}-4p,p\right),\\\boldsymbol Q={}&\left(q+\frac{65}{768},\frac{505}{768}-4q,6q-\frac{341}{768},\frac{539}{768}-4q,q\right).\end{aligned}',True)+tex(r'\begin{aligned}X&=-\frac{(1024p-255)(3072p-425)}{2895532523520},\\Y&=-\frac{p(768p-241)}{13056},\\Z&=\frac{25690112p^2-9670144p+770185}{68941250560},\\z&=\sqrt X,\qquad w=\frac{Z+i\sqrt{XY-Z^2}}{\sqrt X}.\end{aligned}',True)+tex(r'\begin{aligned}\boldsymbol\alpha&=(-1820,3,-14/33,1,0),\\\boldsymbol\beta&=(-3,2/455,-1/2145,0,1),\\x_i&=\alpha_i z+\beta_i w.\end{aligned}',True)+'<p>Next form four positive lengths and a unit phase:</p>'+tex(r'\begin{aligned}\boldsymbol h&=(14,2002,2002,14),\\\ell_i^2&=\frac{h_i^2P_{i+1}Q_i}{\binom{17}{4i+4}\binom{17}{4i+1}},\qquad 0\le i\le3,\\\eta&=\frac{1-r^2+2ir}{1+r^2},\qquad |\eta|=1.\end{aligned}',True)+tex(r'\begin{aligned}S&=\ell_0+\ell_1\eta,\qquad R=|S|^2,\\d&=\frac{R+\ell_2^2-\ell_3^2}{2},\qquad\Delta=\ell_2^2R-d^2,\\e_0&=\ell_0,\qquad e_1=\ell_1\eta,\\e_2&=-\frac{S(d+i\sqrt\Delta)}{R},\qquad e_3=-S-e_2.\end{aligned}',True)+'<p>All square roots are the nonnegative real roots. The formula applies on the domain</p>'+tex(r'P_i,Q_i>0,\quad X>0,\quad XY-Z^2>0,\quad R>0,\quad\Delta\ge0.',True)+'<p>Both parameter choices above lie strictly inside this domain. Changing the sign of '+tex(r'i\sqrt\Delta')+' in the formula for '+tex(r'e_2')+' gives another allowed branch. The two reported choices use the displayed plus sign.</p><h3>The simple point has rational probabilities</h3>'+tex(r'\begin{aligned}\boldsymbol P&=\frac1{768}(95,159,229,125,160),\\\boldsymbol Q&=\frac1{768}(146,181,145,215,81),\qquad\eta=i.\end{aligned}',True)+tex(r'XY-Z^2=\frac{1046084177}{2199911876176644145152}>0,\qquad\Delta=\frac{1057861}{11350123846041600}>0.',True)+'</section>')
    add('<section id="proof"><h2>Why the entire span is AC</h2><p>The two supports are disjoint. The probabilities obey the uniform spin-moment identities</p>'+tex(r'\sum_{i=0}^4P_i(4i)^a=\sum_{i=0}^4Q_i(4i+1)^a=\frac1{18}\sum_{j=0}^{17}j^a,\qquad a=0,1,2,3.',True)+'<p>Thus the vectors are normalized and orthogonal. Occupied indices in each vector differ by four, making both three-qubit self reductions diagonal; the moment identities fix every diagonal entry at '+tex(r'1/4')+'.</p><h3>The cross reductions also vanish</h3><p>The three possible cross entries with shift one are proportional to the rows of</p>'+tex(r'K\boldsymbol x=0,\qquad K=\begin{pmatrix}1&1001&3003&91&0\\0&1092&10296&1092&0\\0&91&3003&1001&1\end{pmatrix}.',True)+'<p>Both '+tex(r'\boldsymbol\alpha')+' and '+tex(r'\boldsymbol\beta')+' lie in this kernel. Their squared magnitudes satisfy the exact rational identities</p>'+tex(r'|x_i|^2=\alpha_i^2X+\beta_i^2Y+2\alpha_i\beta_iZ=\frac{P_iQ_i}{\binom{17}{4i}\binom{17}{4i+1}}.',True)+'<p>The four constructed edges close and have the required lengths:</p>'+tex(r'\sum_{i=0}^3e_i=0,\qquad |e_i|^2=\ell_i^2.',True)+'<p>The recurrence consequently fixes both probability lists and makes the last possible cross entry, with shift three, vanish:</p>'+tex(r'\sum_{i=0}^3h_i a_{i+1}\overline{b_i}=\sum_{i=0}^3h_i\frac{a_{i+1}}{a_i}x_i=\sum_{i=0}^3e_i=0.',True)+'<div class="result">'+tex(r'\boxed{R_3(|u_a\rangle\langle u_b|)=\delta_{ab}\frac{I_4}{4},\qquad(u_1,u_2)=(u,v).}',True)+'<p>Every normalized complex superposition in the two-dimensional span is third-order AC.</p></div><p>The primary verifier checks all 64 ordered cross-reduction entries directly at the simple point. A separate family verifier checks the general moment and product identities, together with exact rational enclosures certifying the source reconstruction.</p><h3>The displayed simple basis vectors have exactly order three</h3>'+tex(r'(\rho_4^u)_{00}=\frac{1099}{5440}=\frac15+\frac{11}{5440},\qquad(\rho_4^v)_{00}=\frac{653}{3264}=\frac15+\frac1{16320}.',True)+'<p>These entries exclude fourth-order AC for the two displayed vectors. They do not classify the order of every superposition.</p><h3>Why dimension two is optimal</h3><p>Rectangular spin tensors of ranks one half and three halves give six mutually orthogonal images per basis vector of any third-order AC code. The images lie in the 17-dimensional symmetric space of sixteen qubits:</p>'+tex(r'6k\le17\quad\Longrightarrow\quad k\le2.',True)+'<p>The analytical construction supplies dimension two. This upper bound applies to arbitrary complex subspaces. <a href="proof.tex">The complete LaTeX proof</a> gives the tensor normalization and full argument.</p></section>')
    add('<section id="source"><h2>Relationship to the numerical Julia plane</h2><p>The source is John Martin’s '+tex(r'\Pi_{17,2,3}')+' at <a href="../../references/ACLiege.jl">ACLiege.jl, line 939</a>. Its two support patterns reveal the probability families above. The cross conditions impose '+tex(r'p+q=241/768')+' and reduce the remaining phases to the closed quadrilateral.</p><p>The rational parameters '+tex(r'p_*,r_*')+' reconstruct this reported plane after a common collective rotation and independent basis-vector phases. The maximum Dicke-coefficient discrepancies are '+tex(r'1.73\times10^{-10}')+' and '+tex(r'2.48\times10^{-10}')+'.</p><div class="source-note"><p>The family identities and exact domain certificate establish existence. Numerical agreement identifies the reconstruction; it does not equate exact states with rounded decimal vectors. The simple point '+tex(r'p=5/24,r=1')+' is an additional representative of the family.</p></div><p>No classification of every optimal third-order plane or claim of literature priority is made.</p></section>')
    downloads=[('basis.json','Simple-point analytical basis','All ordinary radical Dicke expressions at p=5/24, r=1.'),('source-reconstruction.json','Analytical source reconstruction','All radical coefficients at the certified rational source parameters.'),('proof.tex','Complete LaTeX proof','Family, cross identities, source relation and optimal dimension.'),('verify.py','Primary verifier','Direct exact normalized-Dicke reductions for all basis pairs.'),('verification.json','Exact verification report','All 64 cross entries and normalization checks.'),('verify_family.py','Family and source verifier','General symbolic identities and a rational parameter-domain certificate.'),('family-verification.json','Family verification report','Exact admissibility and numerical source comparison.'),('verify_independently.py','Independent verifier','Separate reconstruction of the physical AC conditions.'),('independent-verification.json','Independent report','Independent exact checks of the analytical plane.'),('geometry.json','Majorana coordinates','Constellations for the two displayed basis vectors.'),('geometry-verification.json','Majorana verification','Multiplicity and state-reconstruction checks.'),('build_page.py','Page generator','Rebuild this page with the bundled offline assets.')]
    add('<section id="files"><h2>Downloads and reproducibility</h2><div class="download-grid">'+''.join('<div><a href="'+url+'">'+label+' ↓</a><small>'+note+'</small></div>' for url,label,note in downloads)+'</div></section><footer><p>Anticoherent subspaces · 30 October 2026</p><a href="../../index.html#n=17&amp;t=3&amp;subspace=radical-n17-k2-t3">Return to the catalogue ↗</a></footer>')
    head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seventeen qubits: an analytical third-order AC plane</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
    (HERE/'index.html').write_text(head+''.join(pieces)+'</main></body></html>\n')
if __name__=='__main__':main()
